import * as z from "zod/v4";
import { allowAll, defineChannel, localDevStrict, loopbackOnly, POST, sharedSecretAuth, } from "../../channels.js";
import { withPropagatingBackgroundErrors } from "../../internal/channel-dispatch.js";
import { normalizeIdentity } from "../../internal/continuation-identity.js";
import { isDevMode } from "../../internal/dev-mode.js";
import { attachHostedAdmissionAdapter } from "../../internal/hosted-admission-adapter.js";
import { replayCatchRequest } from "../../internal/hosted-catch.js";
import { AGENT_SDK_CATCH_EVENT_TYPE } from "../../internal/hosted-catch-protocol.js";
import { envSecretRef, namedWebhookSecretArchitectureError, } from "../../internal/named-webhook-secret.js";
import { isSecretRef } from "../../types.js";
import { createPendingCursorGitLabCredentials, parseCursorGitLabProjectScope, registerGitLabCursorAccountRuntime, } from "./cursor-account.js";
import { deriveGitLabWebhookEvents, GITLAB_CHANNEL_KIND } from "./events.js";
import { dispatchGitLabWebhook, GITLAB_TOKEN_HEADER, GITLAB_WEBHOOK_SECRET_ENV, handleGitLabWebhookRequest, parseGitLabWebhookPayload, } from "./gitlab-webhook.js";
import { emptyGitLabChannelState } from "./state.js";
const gitlabChannelOptionsByDefinition = new WeakMap();
export function getGitLabChannelOptions(definition) {
    return gitlabChannelOptionsByDefinition.get(definition);
}
/**
 * Why a `gitlabChannel` cannot deploy onto architecture v2 as authored, or
 * `undefined` when it can: v2 needs a named `webhookSecret` so the control
 * plane can compare `X-Gitlab-Token` before any compute starts.
 */
export function gitlabChannelArchitectureError(definition) {
    const options = getGitLabChannelOptions(definition);
    if (options === undefined) {
        return undefined;
    }
    return namedWebhookSecretArchitectureError({
        option: "gitlabChannel webhookSecret",
        webhookSecret: options.webhookSecret,
        envName: GITLAB_WEBHOOK_SECRET_ENV,
        verifies: "X-Gitlab-Token",
    });
}
/**
 * The route policy for a GitLab webhook whose secret is named: compare
 * `X-Gitlab-Token` against the env var / deployment secret `secretName`.
 * Being a {@link sharedSecretAuth} policy, `deploy` writes it into the
 * manifest, so on Cursor hosting the control plane runs the same compare at
 * ingestion, refuses a bad token before any compute starts, and strips the
 * header (it is the secret) before the request reaches the guest.
 */
export function gitlabWebhookTokenAuth(secretName) {
    return sharedSecretAuth({ header: GITLAB_TOKEN_HEADER, secret: secretName });
}
/**
 * Default route auth for the resolved webhook secret:
 *
 * - A named secret makes the token compare the route policy itself
 *   ({@link gitlabWebhookTokenAuth}), which is also what makes the channel
 *   catchable on the control plane.
 * - A literal or getter secret keeps the compare inside the handler, so
 *   the route admits everything (allowAll) and the handler is the request
 *   auth.
 * - No secret: prod stays loopback-strict; `--dev` admits loopback only.
 *   `isDevMode()` is read per request: channel modules construct at import.
 */
function defaultGitLabRouteAuth(webhookSecret) {
    if (webhookSecret === undefined) {
        return [(request, info) => (isDevMode() ? loopbackOnly() : localDevStrict())(request, info)];
    }
    if (isSecretRef(webhookSecret)) {
        return [gitlabWebhookTokenAuth(webhookSecret.secretName)];
    }
    return [allowAll()];
}
export function gitlabChannel(options = {}) {
    const routePath = options.path ?? "/";
    // The env fallback is named, not read, so it deploys like an authored
    // `{ secretName: "GITLAB_WEBHOOK_SECRET" }` and the handler resolves the
    // same name per request.
    const webhookSecret = options.webhookSecret ?? envSecretRef(GITLAB_WEBHOOK_SECRET_ENV);
    const auth = options.auth ?? defaultGitLabRouteAuth(webhookSecret);
    const channelOptions = { ...options, webhookSecret };
    if (channelOptions.continuation !== undefined) {
        channelOptions.continuation = normalizeIdentity(channelOptions.continuation, GITLAB_CHANNEL_KIND);
    }
    // `cursorAccount` routes `ctx.gitlab` through the SCM proxy once the serve
    // host binds the Cursor API key + transport (`--cursor-scm-proxy`).
    const cursorAccount = options.cursorAccount === undefined || options.cursorAccount === false
        ? undefined
        : {
            credentials: createPendingCursorGitLabCredentials(),
            scope: typeof options.cursorAccount === "object"
                ? parseCursorGitLabProjectScope(options.cursorAccount.projects)
                : undefined,
        };
    const proxy = () => cursorAccount?.credentials.getProxyTransport();
    const definition = defineChannel({
        auth,
        state: emptyGitLabChannelState(),
        events: options.events ?? {},
        onStart: options.onStart,
        onStop: options.onStop,
        meta: {
            kind: GITLAB_CHANNEL_KIND,
            gitlabWebhookEvents: deriveGitLabWebhookEvents(channelOptions),
        },
        routes: [
            POST(routePath, {
                bodySchema: z.unknown(),
                description: "GitLab webhook ingress",
                handler: async (request, args) => handleGitLabWebhookRequest({
                    options: channelOptions,
                    request,
                    args,
                    proxy,
                }),
            }),
        ],
    });
    gitlabChannelOptionsByDefinition.set(definition, channelOptions);
    if (cursorAccount !== undefined) {
        registerGitLabCursorAccountRuntime(definition, {
            options: channelOptions,
            ...cursorAccount,
        });
    }
    attachHostedAdmissionAdapter(definition, {
        kind: GITLAB_CHANNEL_KIND,
        prepareArgs: withPropagatingBackgroundErrors,
        dispatch: async ({ channelId, eventType, payload, deliveryId, args }) => {
            // Replay an http.request envelope. Pass the channel auth so a public
            // chain does not receive the catch principal. Cursor-account
            // deliveries stay on dispatchGitLabWebhook.
            if (eventType === AGENT_SDK_CATCH_EVENT_TYPE) {
                return replayCatchRequest({
                    channelId: channelId ?? GITLAB_CHANNEL_KIND,
                    deliveryId,
                    routes: definition.routes ?? [],
                    payload,
                    args,
                    auth,
                });
            }
            const delivery = parseGitLabWebhookPayload(payload, eventType);
            if (delivery === null) {
                return Response.json({ ok: false, error: "invalid_gitlab_payload" }, { status: 400 });
            }
            delivery.deliveryId = deliveryId;
            return dispatchGitLabWebhook({
                options: channelOptions,
                delivery,
                args,
                proxy,
            });
        },
    });
    return definition;
}
export function findGitLabChannelTargets(mounts) {
    const targets = [];
    for (const { slug, project } of mounts) {
        for (const channel of project.channels) {
            const meta = channel.definition.meta;
            if (meta?.kind !== GITLAB_CHANNEL_KIND) {
                continue;
            }
            const postRoute = (channel.definition.routes ?? []).find((route) => route.method === "POST");
            targets.push({
                slug,
                channelId: channel.id,
                routePath: postRoute?.path ?? "/",
                events: [...(meta.gitlabWebhookEvents ?? [])],
            });
        }
    }
    return targets;
}
